        ["semanticTemplateID"] = "semantic.combat.kill.killer.shaken.firearm_low_01",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "Jesus... I actually hit it.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.01",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral01",
                },
                {
                    ["fallback"] = "My hands are shaking... but it's down.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.02",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral02",
                },
                {
                    ["fallback"] = "Did I get it? God, I think it's dead.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.03",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral03",
                },
                {
                    ["fallback"] = "That was way too close...",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.04",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral04",
                },
                {
                    ["fallback"] = "I panicked and fired... thank God.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.05",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral05",
                },
                {
                    ["fallback"] = "Is it dead? Please tell me it's dead.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.06",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral06",
                },
                {
                    ["fallback"] = "Heart's beating out of my chest...",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.07",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral07",
                },
                {
                    ["fallback"] = "I didn't think that shot would land.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.08",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral08",
                },
                {
                    ["fallback"] = "It's down... don't let another one get close.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.09",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral09",
                },
                {
                    ["fallback"] = "God... that sound... it's finally quiet.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.firearm_low_01.neutral.10",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenFirearmLow01Neutral10",
                },
            },
        },
    },
    ["semantic.combat.kill.killer.shaken.unarmed_01"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_KILL_KILLER_SHAKEN_UNARMED_01",
        ["contentOwner"] = "projecthoomans.dialogue_content.events",
        ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01",
        ["semanticTemplateID"] = "semantic.combat.kill.killer.shaken.unarmed_01",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "Oh God. I did that with my hands.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.01",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral01",
                },
                {
                    ["fallback"] = "I had to shove it down... my bare hands.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.02",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral02",
                },
                {
                    ["fallback"] = "It almost bit me. Look at my arms shaking.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.03",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral03",
                },
                {
                    ["fallback"] = "I need a weapon. I can't do that again.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.04",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral04",
                },
                {
                    ["fallback"] = "I felt its teeth scrape near my jacket.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.05",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral05",
                },
                {
                    ["fallback"] = "Stomped on its head... God forgive me.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.06",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral06",
                },
                {
                    ["fallback"] = "That was pure desperation.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.07",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral07",
                },
                {
                    ["fallback"] = "My hands are bruised... but I'm alive.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.08",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral08",
                },
                {
                    ["fallback"] = "Never want to be that close again.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.09",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral09",
                },
                {
                    ["fallback"] = "It's dead... I pushed it off and stomped.",
                    ["id"] = "phrase.semantic.combat.kill.killer.shaken.unarmed_01.neutral.10",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerShakenUnarmed01Neutral10",
                },
            },
        },
    },
    ["semantic.combat.kill.killer.supportive.firearm_01"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_KILL_KILLER_SUPPORTIVE_FIREARM_01",
        ["contentOwner"] = "projecthoomans.dialogue_content.events",
        ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01",
        ["semanticTemplateID"] = "semantic.combat.kill.killer.supportive.firearm_01",
        ["styles"] = {
            ["neutral"] = {
                {
