                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.01",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral01",
                },
                {
