                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.02",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral02",
                },
                {
                    ["fallback"] = "Downed that one. I've got your back.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.03",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral03",
                },
                {
                    ["fallback"] = "Clear! You hurt anywhere?",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.04",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral04",
                },
                {
                    ["fallback"] = "Got him off us. Stay close.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.05",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral05",
                },
                {
                    ["fallback"] = "Dropped that one. Keep your eyes open.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.06",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral06",
                },
                {
                    ["fallback"] = "Took care of it. Are you alright?",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.07",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral07",
                },
                {
                    ["fallback"] = "Shot landed. You safe?",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.08",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral08",
                },
                {
                    ["fallback"] = "Target down. Covering you.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.09",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral09",
                },
                {
                    ["fallback"] = "That one's finished. Watch the flanks.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.firearm_01.neutral.10",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveFirearm01Neutral10",
                },
            },
        },
    },
    ["semantic.combat.kill.killer.supportive.melee_01"] = {
        ["canonicalConcept"] = "SEMANTIC_COMBAT_KILL_KILLER_SUPPORTIVE_MELEE_01",
        ["contentOwner"] = "projecthoomans.dialogue_content.events",
        ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01",
        ["semanticTemplateID"] = "semantic.combat.kill.killer.supportive.melee_01",
        ["styles"] = {
            ["neutral"] = {
                {
                    ["fallback"] = "It's down. Keep close.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.01",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral01",
                },
                {
                    ["fallback"] = "Got it off you. You alright?",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.02",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral02",
                },
                {
                    ["fallback"] = "Downed it. Check your corners.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.03",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral03",
                },
                {
                    ["fallback"] = "I'm right here with you. It's dead.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.04",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral04",
                },
                {
                    ["fallback"] = "Crushed it before it got close.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.05",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral05",
                },
                {
                    ["fallback"] = "Stay behind me. That one's done.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.06",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral06",
                },
                {
                    ["fallback"] = "Took it down. Catch your breath.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.07",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral07",
                },
                {
                    ["fallback"] = "Dead on the floor. You holding up?",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.08",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral08",
                },
                {
                    ["fallback"] = "I've got this line. Watch behind us.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.09",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral09",
                },
                {
                    ["fallback"] = "It's over for that one. We're okay.",
                    ["id"] = "phrase.semantic.combat.kill.killer.supportive.melee_01.neutral.10",
                    ["key"] = "UI_PNC_Conversation_Content_SemanticCombatKillKillerSupportiveMelee01Neutral10",
                },
            },
        },
    },
